score, reasons = 0, []
if p["industry"] in icp["industries"]: score += 3
else: reasons.append("industry outside niche")
lo, hi = icp["staff"]
if lo <= p["staff"] <= hi: score += 2
else: reasons.append("size outside range")
hits = len(icp["signals"] & set(p["signals"]))
score += min(hits, 2) * 2
if hits == 0: reasons.append("no pain signals")
if p["budget"] >= icp["min_budget"]: score += 2
else: reasons.append("budget too small")
return score, reasons

plan = {c["name"]: 0 for c in channels}
left = hours
for c in sorted(channels, key=lambda c: -c["meetings_per_hour"]):
    h = min(c["max_hours"], left)
    plan[c["name"]] = h
    left -= h
    if left <= 0: break
meetings = sum(plan[c["name"]] * c["meetings_per_hour"] for c in channels)
return plan, round(meetings, 2)

issues = []
words = len(body.split())
if words > 120: issues.append(f"too long ({words} words)")
if len(subject) > 60: issues.append("subject over 60 characters")
if re.search(r"hope (this|you).{0,20}well", body, re.I): issues.append("generic opener")
first = body.split("\n\n")[1] if "\n\n" in body else body
if re.match(r"\s*(i am|i'm|my name is)\b", first, re.I): issues.append("opens about yourself")
if body.count("?") != 1: issues.append("needs exactly one question as the ask")
if len(re.findall(r"https?://", body)) > 1: issues.append("more than one link")
if "{" in body or "}" in body: issues.append("unfilled placeholder")
return issues
